// Generate the runtime art from the reviewed study; no gameplay/camera code is copied.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const src=fs.readFileSync(path.join(root,'docs/proposals/gym-redesign/gym-redesign.js'),'utf8').replace(/\r\n/g,'\n');
const section=(from,to)=>{const a=src.indexOf(from),b=src.indexOf(to,a);if(a<0||b<0)throw Error('Missing gym source anchor: '+from);return src.slice(a,b)};
let body=[
 '/* Generated by tools/make_social_gym.mjs from docs/proposals/gym-redesign/gym-redesign.js. */',
 'window.PGSocialGymRedesign={async build(scene){',"'use strict';",'const T=THREE;',
 section('/* ---- 0. world contract','/* ---- 1. renderer'),
 section('/* ---- 2. textures','/* ---- 3. geometry'),
 section('/* ---- 3. geometry','/* ---- 5. architecture'),
 section('/* ---- 5. architecture','/* ---- 8. build everything'),
 section('/* ---- 8. build everything','/* ground apron:'),
 'court.userData.sanctuaryGym=true;',
 "for(const [sx,name] of [[52,'power'],[63,'guard'],[75,'agility'],[86,'focus']]){",
 'const marker=new T.Mesh(new T.BoxGeometry(.02,.02,.02),new T.MeshBasicMaterial());',
 'marker.position.set(sx,.03,34);marker.userData.sanctuaryStation=name;scene.add(marker);}',
 'return {triangles:Math.round(triangles)};','}};',''
].join('\n');
body=body.replace(/load\('\.\.\/\.\.\/\.\.\/assets\//g,"load('assets/")
 .replace("const AUDIT=new URLSearchParams(location.search).get('audit')==='1';",'const AUDIT=false;')
 .replace('  mesh.position.set((b.x1+b.x2)/2,.035,(b.z1+b.z2)/2);\n  scene.add(mesh);','  mesh.position.set((b.x1+b.x2)/2,.035,(b.z1+b.z2)/2);\n  mesh.userData.gymZone=key;\n  scene.add(mesh);');
const dest=path.join(root,'assets/social-gym-redesign.js');
if(process.argv.includes('--check')){if(fs.readFileSync(dest,'utf8')!==body)throw Error('Regenerate assets/social-gym-redesign.js');console.log('PASS generated gym matches reviewed source')}
else {fs.writeFileSync(dest,body);console.log('Generated assets/social-gym-redesign.js')}
